(function(root,factory){const api=factory(root.KanjiTraits||(typeof require==='function'?require('./character-traits.js'):null));if(typeof module==='object'&&module.exports)module.exports=api;else root.KanjiTrialThemes=api;})(typeof window!=='undefined'?window:globalThis,function(Traits){
 'use strict';
 const levels=[10,30,60,100],points=(a,b,c)=>[a,b,c].map(([x,y,angle=0])=>({x,y,angle}));
 const definitions=[
  {id:'link',name:'連携の試練',medal:'連携攻略章',chars:['風','合','口'],points:points([-.32,.40],[.32,.40],[0,.71]),hint:'風の近くを通るコマは加速し、合は仲間の発射に追撃を合わせます。風・合から先に落とすと連携を崩せます。',priorities:['magnet','resonance','charge','guard','chase']},
  {id:'rotation',name:'回転の試練',medal:'回転攻略章',chars:['回','山','独'],points:points([0,.40,Math.PI/4],[-.48,.64,Math.PI/3],[.48,.64,-Math.PI/3]),hint:'回の回転中は横に弾かれやすくなります。山の弱体化を受けるコマを考え、独を最後に残さない作戦も試しましょう。',priorities:['counter','strike','chase','backwater','charge']},
  {id:'breakthrough',name:'突破の試練',medal:'突破攻略章',chars:['矢','小','一'],points:points([0,.42],[-.47,.66],[.47,.66,Math.PI/2]),hint:'矢は直進を保ち、小は発射後に自分の仲間をすり抜けます。正面に固まらず、進路をずらして側面から当ててみましょう。',priorities:['strike','chase','return','brake','charge']},
  {id:'impact',name:'衝撃の試練',medal:'衝撃攻略章',chars:['大','弾','十'],points:points([0,.38],[-.43,.67],[.43,.67]),hint:'大の衝撃波と十の進路変更は近くの別の相手にも届きます。自分同士の間隔を空け、弾の跳ね返り先にも注意しましょう。',priorities:['strike','chase','charge','counter','guard']},
  {id:'iron',name:'鉄壁の試練',medal:'鉄壁攻略章',chars:['盾','凹','粘'],points:points([-.42,.42],[.42,.42],[0,.73]),hint:'盾は正面に強く、凹はくぼみで捕縛します。横や背後を狙い、粘着防御のコマも1体ずつ崩してみましょう。',priorities:['guard','anchor','counter','sturdy','dodge','glide']},
  {id:'boss',name:'総合試練',medal:'総合攻略章',chars:['盾','回','矢'],points:points([0,.38],[-.44,.65,Math.PI/4],[.44,.65]),hint:'盾の守り・回の回転・矢の直進を組み合わせた部隊です。自分の配置と倒す順番を決め、得意な能力で1体ずつ攻略しましょう。',priorities:['guard','counter','charge','strike','chase'],boss:true}
 ];
 const copy=t=>({...t,chars:t.chars.slice(),points:t.points.map(p=>({...p})),priorities:t.priorities.slice(),shotTarget:t.boss?8:6});
 function themesFor(database=null){const available=new Set(Traits.catalogue.map(t=>t.char).filter(c=>!database||database.some(i=>i.char===c))),base=definitions.filter(t=>t.chars.every(c=>available.has(c))),covered=new Set(base.filter(t=>!t.boss).flatMap(t=>t.chars)),extra=[...available].filter(c=>!covered.has(c)),added=[];for(let n=0;n<extra.length;n+=3){const original=extra.slice(n,n+3),chars=original.slice();for(const c of available)if(chars.length<3&&!chars.includes(c))chars.push(c);if(chars.length===3)added.push({id:'extra-'+original.map(c=>c.codePointAt(0).toString(16)).join('-'),name:original.join('・')+'の試練',chars,points:points([-.42,.43],[.42,.43],[0,.73]),hint:'追加された特殊文字の部隊です。挑戦前に各文字をタップして特性を確認し、相手の得意な当たり方を避けてみましょう。',priorities:['charge','guard','strike','counter']});}return [...base.filter(t=>!t.boss),...added,...base.filter(t=>t.boss)].map(copy);}
 const get=(id,database)=>themesFor(database).find(t=>t.id===id),row=(state,id,level)=>state?.specialThemeProgress?.[id]?.[String(level)]||{cleared:false,intact:false,efficient:false,bestShots:null,bestSurvivors:0};
 function canChallenge(state,id,level,database=null){const theme=get(id,database);if(!theme||!levels.includes(level))return false;return !theme.boss||row(state,id,level).cleared||themesFor(database).filter(t=>!t.boss).every(t=>row(state,t.id,level).cleared);}
 function record(state,id,level,won,shots,survivors){const theme=get(id);if(!won||!theme||!canChallenge(state,id,level)||!Number.isInteger(shots)||shots<0||shots>1000||!Number.isInteger(survivors)||survivors<0||survivors>3)return null;state.specialThemeProgress=state.specialThemeProgress||{};const old=row(state,id,level),next={cleared:true,intact:old.intact||survivors===3,efficient:old.efficient||shots<=theme.shotTarget,bestShots:old.bestShots===null?shots:Math.min(old.bestShots,shots),bestSurvivors:Math.max(old.bestSurvivors,survivors)};state.specialThemeProgress[id]=state.specialThemeProgress[id]||{};state.specialThemeProgress[id][String(level)]=next;return next;}
 function nextTheme(run,state,database){if(!run?.themeId||!run.finished||!run.won)return null;const all=themesFor(database),remaining=all.find(t=>!t.boss&&!row(state,t.id,run.difficultyLevel).cleared);if(remaining)return remaining;const boss=all.find(t=>t.boss);return boss&&!row(state,boss.id,run.difficultyLevel).cleared&&canChallenge(state,boss.id,run.difficultyLevel,database)?boss:null;}
 function validProgress(value){return !!value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).length<=100&&Object.entries(value).every(([id,p])=>/^[a-z][a-z0-9-]{0,90}$/.test(id)&&p&&typeof p==='object'&&!Array.isArray(p)&&Object.keys(p).length<=4&&Object.entries(p).every(([level,r])=>levels.includes(Number(level))&&r&&['cleared','intact','efficient'].every(k=>typeof r[k]==='boolean')&&(!(r.intact||r.efficient)||r.cleared)&&(r.bestShots===null||Number.isInteger(r.bestShots)&&r.bestShots>=0&&r.bestShots<=1000)&&Number.isInteger(r.bestSurvivors)&&r.bestSurvivors>=0&&r.bestSurvivors<=3));}
 const medalKey=id=>'trialTheme'+id[0].toUpperCase()+id.slice(1)+'Level';
 const badges=definitions.flatMap(t=>[10,60,100].map((level,tier)=>({id:'trial-'+t.id+'-'+['bronze','silver','gold'][tier],kind:'trial-'+t.id,name:t.medal+'・'+['銅','銀','金'][tier],key:medalKey(t.id),value:level,tier,condition:`Lv.${level}以上の${t.name}に勝利し、「全員生還」「${t.boss?8:6}発以内」をともに達成（別の勝利での達成も可）`})));
 function progress(state){return Object.fromEntries(definitions.map(t=>[medalKey(t.id),Math.max(0,...levels.filter(level=>{const r=row(state,t.id,level);return r.cleared&&r.intact&&r.efficient;}))]));}
 const storageKey='kanji-special-themes-v1';
 function mergeProgress(...sources){const out={};for(const source of sources){if(!validProgress(source))continue;for(const [id,rows]of Object.entries(source))for(const [level,r]of Object.entries(rows)){const before=out[id]?.[level];out[id]??={};out[id][level]={cleared:!!(before?.cleared||r.cleared),intact:!!(before?.intact||r.intact),efficient:!!(before?.efficient||r.efficient),bestShots:Math.min(...[before?.bestShots,r.bestShots].filter(Number.isInteger))===Infinity?null:Math.min(...[before?.bestShots,r.bestShots].filter(Number.isInteger)),bestSurvivors:Math.max(before?.bestSurvivors||0,r.bestSurvivors)};}}return out;}
 function readJournal(storage){try{const value=JSON.parse(storage.getItem(storageKey)||'{}');return validProgress(value)?value:{};}catch{return {};}}
 function restore(state,storage,backups=[]){const medalProof={};for(const theme of definitions){const level=state.iconProgress?.[medalKey(theme.id)];if(levels.includes(level)&&level>0)medalProof[theme.id]={[level]:{cleared:true,intact:true,efficient:true,bestShots:null,bestSurvivors:3}};}state.specialThemeProgress=mergeProgress(state.specialThemeProgress,readJournal(storage),...backups.map(b=>b.specialThemeProgress),medalProof);return state.specialThemeProgress;}
 function persist(state,storage){state.specialThemeProgress=mergeProgress(state.specialThemeProgress,readJournal(storage));storage.setItem(storageKey,JSON.stringify(state.specialThemeProgress));return state.specialThemeProgress;}
 return{storageKey,mergeProgress,restore,persist,levels,definitions,themesFor,get,row,canChallenge,record,nextTheme,validProgress,badges,progress,medalKey};
});
